<script setup>
import {computed} from 'vue';
const props=defineProps(['rows','series','title','percent']);const maximum=computed(()=>props.percent?100:Math.max(1,...props.rows.flatMap(r=>props.series.map(s=>Number(r[s.key])||0)))*1.12);const step=computed(()=>540/Math.max(1,props.rows.length));const y=v=>220-(Number(v)||0)/maximum.value*185;const colors=['var(--vrise-copper)','var(--vrise-gold)','var(--vrise-umber)'];const format=n=>n==null?'—':props.percent?n+'%':new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(n/10000000)+'L';
</script>
<template><div class="metric-chart"><svg v-if="rows.length" viewBox="0 0 620 280" role="img" :aria-label="title" class="chart-svg"><title>{{title}}</title><g v-for="i in [0,1,2,3,4]" :key="i"><line x1="65" x2="605" :y1="220-i*46.25" :y2="220-i*46.25" stroke="var(--vrise-linen)"/><text x="57" :y="224-i*46.25" text-anchor="end" class="chart-label">{{format(maximum*i/4)}}</text></g><g v-for="(r,index) in rows" :key="index"><rect v-for="(s,j) in series" :key="s.key" :x="65+index*step+step*.1+j*(step*.8/series.length)" :y="y(r[s.key])" :width="Math.max(1,Math.min(40,step*.8/series.length-3))" :height="220-y(r[s.key])" :fill="colors[j]" rx="3"><title>{{r.month||r.label}} · {{s.label}}: {{format(r[s.key])}}</title></rect><text :x="65+(index+.5)*step" y="242" text-anchor="middle" class="chart-label">{{r.month||r.label}}</text></g></svg><div v-else class="empty-state">No measurements recorded yet.</div><div class="chart-legend"><span v-for="(s,i) in series" :key="s.key"><i :style="{background:colors[i]}"/>{{s.label}}</span></div><details v-if="rows.length" class="chart-data"><summary>View chart values</summary><div class="table-scroll"><table class="orders-table"><thead><tr><th>PERIOD</th><th v-for="s in series" :key="s.key">{{s.label}}</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r.month||r.label}}</td><td v-for="s in series" :key="s.key">{{format(r[s.key])}}</td></tr></tbody></table></div></details></div></template>
